type ElementProps<Options, Handle> = Options & {
	/** The element's live handle (same surface as the vanilla `create` return). */
	ref?: Ref<Handle>;
	/** Applied to the element's mount container (the wrapper this component renders; the element itself lives in its own frame, see the Styling docs for restyling it). */
	className?: string;
	/** Applied to the element's mount container (the wrapper this component renders). */
	style?: CSSProperties;
	/** Shown until the element is fully loaded. When omitted, the element's own internal loading UI is shown instead. */
	fallback?: ReactNode;
};

/**
 * An account's tracked audience: everyone its pixel has seen, and every event they performed. Scope it to an account with `accountId`, then mount `people`, `events`, or both. They read the same window and the same credit rule, so two surfaces side by side can never disagree about what they are showing. `person` is where a click on either of them leads: one person's whole record, mountable inline or presentable over your page. `links` wires their person links to your own pages.
 * Provider component: creates the TrackingHandle and drives the element components rendered as children. `fallback` shows until every child element has loaded (grouped); `ref` exposes the live handle. Unmounting it destroys the handle and everything it created.
 * @example
 * ```tsx
 * import { WhopElements, Tracking, PeopleElement, EventsElement, PersonElement } from "@whop/elements-react";
 * import { loadWhop } from "@whop/elements";
 * 
 * function Example() {
 *   return (
 *     <WhopElements elements={loadWhop()}>
 *       <Tracking>
 *         <PeopleElement />
 *         <EventsElement />
 *         <PersonElement />
 *       </Tracking>
 *     </WhopElements>
 *   );
 * }
 * ```
 * @see https://docs.whop.com/elements/latest/tracking/overview
 */
export declare function Tracking(
	props: TrackingOptions & { children?: ReactNode; fallback?: ReactNode; ref?: Ref<{ handle: TrackingHandle | null }> },
): ReactNode;
/**
 * The nearest `<Tracking>` ancestor's live handle, `null` until it boots. Must be called under a `<Tracking>`.
 * @see https://docs.whop.com/elements/latest/tracking/overview
 */
export declare function useTracking(): TrackingHandle | null;

/**
 * Everyone the account has seen — visitors and customers resolved from pixel activity, with their source, spend, and activity counters. Search, filter by source, event, geography, or device, sort any column, and page through. A row click follows `links.person` when the handle configures it, and otherwise comes back to you as `personOpened`.
 * @example
 * ```tsx
 * import { WhopElements, Tracking, PeopleElement } from "@whop/elements-react";
 * import { loadWhop } from "@whop/elements";
 * 
 * function Example() {
 *   return (
 *     <WhopElements elements={loadWhop()}>
 *       <Tracking>
 *         <PeopleElement />
 *       </Tracking>
 *     </WhopElements>
 *   );
 * }
 * ```
 * @see https://docs.whop.com/elements/latest/tracking/people
 */
export declare function PeopleElement(props: ElementProps<PeopleElementCreateOptions, PeopleElementHandle>): ReactNode;
/**
 * Every event the account measured — page views, leads, purchases, and custom pixel events — as a raw, filterable stream. The rows behind any metric: filter by event, source, geography, or device over the handle’s window, or search one person’s identifier to read their whole journey. A person cell follows `links.person` when the handle configures it, and otherwise comes back to you as `personOpened`.
 * @example
 * ```tsx
 * import { WhopElements, Tracking, EventsElement } from "@whop/elements-react";
 * import { loadWhop } from "@whop/elements";
 * 
 * function Example() {
 *   return (
 *     <WhopElements elements={loadWhop()}>
 *       <Tracking>
 *         <EventsElement />
 *       </Tracking>
 *     </WhopElements>
 *   );
 * }
 * ```
 * @see https://docs.whop.com/elements/latest/tracking/events
 */
export declare function EventsElement(props: ElementProps<EventsElementCreateOptions, EventsElementHandle>): ReactNode;
/**
 * Everything the account knows about one person: who they are, where they came from, what they have spent, and every event they have performed, in order. The view a person click leads to: mount it on the page `links.person` points at, or present it over your own page when `people` or `events` raise `personOpened`. `identifier` takes any identifier a person has been seen under, so a `personOpened` payload resolves here unchanged.
 * @example
 * ```tsx
 * import { WhopElements, Tracking, PersonElement } from "@whop/elements-react";
 * import { loadWhop } from "@whop/elements";
 * 
 * function Example() {
 *   return (
 *     <WhopElements elements={loadWhop()}>
 *       <Tracking>
 *         <PersonElement />
 *       </Tracking>
 *     </WhopElements>
 *   );
 * }
 * ```
 * @see https://docs.whop.com/elements/latest/tracking/person
 */
export declare function PersonElement(props: ElementProps<PersonElementCreateOptions, PersonElementHandle>): ReactNode;
